jQuery(function($) {
    "use strict";
	var $selectElements = $('#mini-ibe').find('[data-toggle=mvselect]');
	if ($selectElements.length > 0) {
		$selectElements.each(function () {
			var $this = jQuery(this);
			$this.select2({
				theme: 'bootstrap4',
				width: 'style',
				placeholder: $(this).attr('placeholder'),
				allowClear: Boolean($(this).data('allow-clear')),
			  });
		});
	}
	
	$('.pick-pax').on('hide.bs.dropdown', function (e) {
	  if (!e.clickEvent) {
		return true;
	  }
	  var target = $(e.clickEvent.target);
	  return !(target.hasClass('.pick-pax') || target.parents('.pick-pax').length);
	});
	$('#seladults').TouchSpin({
		min: 1,
		max: 9,
		firstclickvalueifempty: 1,
		verticalbuttons: false,
		buttondown_class: "btn btn-secondary rounded",
		buttonup_class: "btn btn-secondary rounded"
	});
	$("#selchildren").TouchSpin({
		min: 0,
		max: 4,
		firstclickvalueifempty: 1,
		verticalbuttons: false,
		buttondown_class: "btn btn-secondary rounded",
		buttonup_class: "btn btn-secondary rounded"
	});
	$("#selinfants").TouchSpin({
		min: 0,
		max: 1,
		firstclickvalueifempty: 1,
		verticalbuttons: false,
		buttondown_class: "btn btn-secondary rounded",
		buttonup_class: "btn btn-secondary rounded"
	});
	$('.pax-count').on('touchspin.on.startspin', function(e){
		var childPerAdult = 4;
		var infantPerAdult = 1;
		var maxAdult = 9;
		var maxChild = 4;
		var maxInfant = 9;
		var totalPax = 0;
		var adults = parseInt($('#seladults').val());
		var children = parseInt($('#selchildren').val());
		var infants = parseInt($('#selinfants').val());
		
		totalPax = adults + children + infants;
		
		maxAdult = 9 - children - infants;
		maxChild = 9 - adults - infants;
		maxInfant = 9 - adults - children;
		
		maxAdult = (maxAdult < 0) ? 0 : maxAdult;
		maxAdult = (totalPax == 9) ? adults : maxAdult;
		maxChild = (maxChild < 0) ? 0 : maxChild;
		maxInfant = (maxInfant < 0) ? 0 : maxInfant;
		maxInfant = (maxInfant != adults && totalPax != 9) ? adults : maxInfant;
		
		$('#seladults').trigger("touchspin.updatesettings", {max: maxAdult});
		$('#selchildren').trigger("touchspin.updatesettings", {max: maxChild});
		$('#selinfants').trigger("touchspin.updatesettings", {max: maxInfant});
		if(totalPax > 1){
			$('#pax-display').text( totalPax + " Passengers");
		}else{
			$('#pax-display').text( totalPax + " Passenger");
		}
	});
});
var ibe = {
    airports: null,
    pairs: null,
	widget: '#ibe-widget',
	last_active : null,
	waiting : false,
	ready : false,
	ibe_tid: 'sb',
    ibe_head_active: null,
    ibe_block_active: null,
	ibe_terms_read: false,
	submit: function(){
		$('.btn-search').attr('disabled', false);
		ibe.waiting = false;
		$(ibe.widget).submit();
	},
    init: function (airports, pairs) {
        ibe.airports = airports;
        ibe.pairs = pairs;
		ibe.ibe_terms_read = false;
		//$('.btn-search').attr('disabled', true);
		qweb.init();
		ibe.last_active = new Date();
        $('#ibe-search').submit(function(){
			ibe.widget = '#ibe-search';
			$('.btn-search').attr('disabled', true);
			if(ibe.validate_search()){
                // if(ibe.airports[$('#seldcity1').val()][1] === "MV" && ibe.airports[$('#selacity1').val()][1] == "MV" && ibe.ibe_terms_read === false){
					// $('#mvtaxmodal').modal("show");
                    // return false;
				// }
		  
				if(ibe.ready){
					$('.btn-search').attr('disabled', false);
                    ibe.ibe_terms_read = false;
                    return true;
                }else{
					ibe.waiting = true;
					ibe.ready = false;
					turnstile.reset(tsWidget);
					turnstile.execute(tsWidget);
					return false;
				}
			}
			$('.btn-search').attr('disabled', false);
            return false;
        });
		
		$('#ibe-myb').submit(function(){
			ibe.widget = '#ibe-myb';
			$('.btn-search').attr('disabled', true);
			if(ibe.validate_myb()){
				if(ibe.ready){
					$('.btn-search').attr('disabled', false);
					return true;
				}else{
					ibe.waiting = true;
					ibe.ready = false;
					turnstile.reset(tsWidget);
					turnstile.execute(tsWidget);
					return false;
				}
			}else{
				$('.btn-search').attr('disabled', false);
				return false;
			}
		});
		$('#ibe-ssci').submit(function(){
			ibe.widget = '#ibe-ssci';
			$('.btn-search').attr('disabled', true);
			if(ibe.validate_ssci()){
				if(ibe.ready){
					$('.btn-search').attr('disabled', false);
					return true;
				}else{
					ibe.waiting = true;
					ibe.ready = false;
					turnstile.reset(tsWidget);
					turnstile.execute(tsWidget);
					return false;
				}
			}else{
				$('.btn-search').attr('disabled', false);
				return false;
			}
		});
		$('#ibe-cge').submit(function(){
			ibe.widget = '#ibe-cge';
			var params  = 'width='+screen.width;
			params += ', height='+screen.height;
			params += ', top=0, left=0'
			params += ', fullscreen=yes';
			params += ', directories=no';
			params += ', location=no';
			params += ', menubar=no';
			params += ', resizable=no';
			params += ', scrollbars=no';
			params += ', status=no';
			params += ', toolbar=no';
			if(ibe.validate_cge()){
				var url = 'https://cargo.maldivian.aero/Tracking/AWB/986-' + $('#awbno').val();
				newwin=window.open(url,'FullWindowAll', params);
				if (window.focus) {newwin.focus()}
				return false;
			}else{
				$('.btn-search').attr('disabled', false);
				return false;
			}
		});
		
		
		$('#ibe-cgw').submit(function(){
			ibe.widget = '#ibe-cgw';
			var params  = 'width='+screen.width;
			params += ', height='+screen.height;
			params += ', top=0, left=0'
			params += ', fullscreen=yes';
			params += ', directories=no';
			params += ', location=no';
			params += ', menubar=no';
			params += ', resizable=no';
			params += ', scrollbars=no';
			params += ', status=no';
			params += ', toolbar=no';
			if(ibe.validate_cgw()){
				var url = 'https://q2expresscargo.cargoflash.com/TrackCONNote.html?CONNote=' + $('#hawbno').val();
				newwin=window.open(url,'FullWindowAll', params);
				if (window.focus) {newwin.focus()}
				return false;
			}else{
				$('.btn-search').attr('disabled', false);
				return false;
			}
		});
		
		$('#mvtaxmodal').on('hide.bs.modal', function() {    
            ibe.ibe_terms_read = true;
			ibe.submit();
        });
		
        $('#seldcity1').change(function(){
			$('#selacity1').empty();
			$("#selacity1").trigger("change");;
			var options = '<option></option>';
			var code = $(this).val();
			var apts = ibe.pairs[code].split(',');
			if(apts !== ''){
				for (var i = 0; i < apts.length; i++) {
					options += '<option value="' + apts[i] + '">' + ibe.airports[apts[i]][0] + '</option>';
				}
			}
			$("#selacity1").html(options);
			$("#selacity1").trigger("change");;
		});
        $('#tid_sb').change(function() {
			if ($(this).is(':checked')) {
				$('#seladate1').attr('disabled',false);
			}
		});
        $('#tid_ow').change(function() {
			if ($(this).is(':checked')) {
				$('#seladate1').val('');
				$('#seladate1').attr('disabled',true);
			}
		});
		
		$('#selddate1').datepickerInFullscreen({
			fakeInput: false,
			format: 'DD-MMM-YYYY',
			beforeOpen : function(modal, settings){
				var till_date = moment($('#seladate1').val(), 'DD-MMM-YYYY');
				if(till_date.isValid()){
					settings.datepicker.endDate 		= till_date.format('YYYY-MM-DD');
					settings.datepicker.defaultViewDate = till_date.format('YYYY-MM-DD');
				}else{
					settings.datepicker.startDate       = new Date();
                    settings.datepicker.endDate         =  moment().add(361, 'days').format('YYYY-MM-DD');
                    settings.datepicker.defaultViewDate = new Date();
                }
			},
		});
		
		$('#seladate1').datepickerInFullscreen({
			fakeInput: false,
			format: 'DD-MMM-YYYY',
			beforeOpen : function(modal, settings){
				var from_date = moment($('#selddate1').val(), 'DD-MMM-YYYY');
				if(from_date.isValid()){
					settings.datepicker.startDate 		= from_date.format('YYYY-MM-DD');
					settings.datepicker.endDate         =  moment().add(361, 'days').format('YYYY-MM-DD');
					settings.datepicker.defaultViewDate = from_date.format('YYYY-MM-DD');
				}else{
                    settings.datepicker.startDate       = new Date();
					settings.datepicker.endDate         =  moment().add(361, 'days').format('YYYY-MM-DD');
                    settings.datepicker.defaultViewDate = new Date();
                }
			},
		});
    },
    validate_search: function () {
        var error = '';
        if (!$('#seldcity1').val()) {
            error += 'Please Select Depature Airport\n';
        }
        if (!$('#selddate1').val()) {
            error += 'Please Select Depature Date\n';
        }
        if (!$('#selacity1').val()) {
            error += 'Please Select Arrival Airport\n';
        }
		if ($('#tid_sb').is(':checked') && !$('#seladate1').val()) {
			error += 'Please Select Arrival Date\n';
		}
        if (!$('#selnationality').val()) {
            error += 'Please Select Nationality\n';
        }
        if (error){
            alert(error);
		}
        return (error === '');
    },
	validate_myb: function(){
		var error = '';
		if (!$('#bookref2').val()) {
            error += 'Please enter your booking reference\n';
        }
		if (!$('#lastname2').val()) {
            error += 'Please enter the booking lastname\n';
        }
		if (error){
            alert(error);
		}
		return (error ==='');
	},
	validate_ssci: function(){
		var error = '';
		if (!$('#bookref3').val()) {
            error += 'Please enter your booking reference\n';
        }
		if (!$('#lastname3').val()) {
            error += 'Please enter the booking lastname\n';
        }
		if (error){
            alert(error);
		}
		return (error ==='');
	},
	validate_cge: function(){
		var error = '';
		if (!$('#awbno').val()) {
            error += 'Please enter your AWB Number\n';
        }else if($('#awbno').val().length !== 8){
			error += 'AWB number should have 8 digits\n';
		}
		if (error){
            alert(error);
		}
		return (error ==='');
	},
	validate_cgw: function(){
		var error = '';
		if (!$('#hawbno').val()) {
            error += 'Please enter your HAWB Number\n';
        }else if($('#hawbno').val().length < 11){
			error += 'HAWB number should have at least 11 digits\n';
		}
		if (error){
            alert(error);
		}
		return (error ==='');
	}
};

var tsWidgets = [];

function renderTurnstileWidgets() {
    var formConfigs = [
        { id: 'ibe-search', action: 'search' },
        { id: 'ibe-myb',    action: 'myb' },
        { id: 'ibe-ssci',   action: 'ssci' }
    ];
    formConfigs.forEach(function(config) {
        var $form = $('#' + config.id);
        if ($form.length) {
            var container = $form.find('.ts-widget')[0]; 
            
            if (container) {
                var widgetId = turnstile.render(container, {
                    sitekey: '0x4AAAAAADTAXXH92o0B5QLu',
                    action: config.action,
                    size: 'invisible',
                    callback: function(token) {
                        $form.find('input[name=weba]').val(token);
                        $('.btn-search').attr('disabled', false);
                        ibe.ready = true;
                        ibe.waiting = false;
                        ibe.submit();
                    },
                    'error-callback': function() {
                        $('.btn-search').attr('disabled', false);
                        ibe.waiting = false;
                    },
                    'expired-callback': function() {
                        ibe.ready = false;
                    }
                });
				tsWidgets.push(widgetId);
            }
        }
    });
}

window.onload = function() {
    renderTurnstileWidgets();
};